import { useCallback, useId, useState, type KeyboardEvent } from 'react';
import { Stack, Input, Tag, Text } from '@jinx-ui/react';

type ArticleTagPickerProps = {
  label?: string;
  placeholder?: string;
  defaultTags?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
};

export default function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  defaultTags = [],
  maxTags,
  onChange,
}: ArticleTagPickerProps) {
  const inputId = useId();
  const [tags, setTags] = useState<string[]>(defaultTags);
  const [draft, setDraft] = useState('');

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange?.(next);
    },
    [onChange],
  );

  const addTag = useCallback(
    (raw: string) => {
      const tag = raw.trim().replace(/\s+/g, ' ');
      if (!tag) return;
      if (maxTags !== undefined && tags.length >= maxTags) return;
      if (tags.some((t) => t.toLowerCase() === tag.toLowerCase())) return;
      commit([...tags, tag]);
    },
    [commit, maxTags, tags],
  );

  const removeTag = useCallback(
    (tag: string) => commit(tags.filter((t) => t !== tag)),
    [commit, tags],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(draft);
      setDraft('');
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      event.preventDefault();
      removeTag(tags[tags.length - 1]);
    }
  };

  const isFull = maxTags !== undefined && tags.length >= maxTags;

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-2)' }}>
      <Input
        id={inputId}
        label={label}
        placeholder={isFull ? 'Достигнут лимит тегов' : placeholder}
        value={draft}
        disabled={isFull}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => {
          addTag(draft);
          setDraft('');
        }}
      />

      {tags.length > 0 ? (
        <Stack
          direction="row"
          wrap
          aria-label="Выбранные теги"
          style={{ gap: 'var(--jx-space-1)' }}
        >
          {tags.map((tag) => (
            <Tag
              key={tag}
              onRemove={() => removeTag(tag)}
              removeLabel={`Удалить тег ${tag}`}
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      ) : (
        <Text size="sm" style={{ color: 'var(--jx-color-text-muted)' }}>
          Теги пока не добавлены
        </Text>
      )}
    </Stack>
  );
}

